import java.util.function.Function;

/**
 * TASK: Practise the two ways of gluing functions together.
 *
 * f.andThen(g) runs f FIRST, then feeds its result to g.
 * f.compose(g) runs g FIRST, then feeds its result to f.
 *
 * andThenApply(f, g, x) must return f.andThen(g) applied to x.
 * composeApply(f, g, x) must return f.compose(g) applied to x.
 *   With f = n -> n * 2 and g = n -> n + 3 and x = 5:
 *     andThenApply -> (5 * 2) + 3 = 13
 *     composeApply -> (5 + 3) * 2 = 16
 *
 * slug(text) builds ONE Function<String, String> by chaining three steps with
 * andThen -- trim the ends, lowercase, then replace every space with '-' --
 * and applies it to text.
 *   slug("  Hello World  ") -> "hello-world"
 */
public class ComposeKit {

    public static int andThenApply(Function<Integer, Integer> f, Function<Integer, Integer> g, int x) {
        return f.andThen(g).apply(x);
    }

    public static int composeApply(Function<Integer, Integer> f, Function<Integer, Integer> g, int x) {
        return f.compose(g).apply(x);
    }

    public static String slug(String text) {
        Function<String, String> trim = String::trim;
        Function<String, String> lower = s -> s.toLowerCase();
        Function<String, String> dashes = s -> s.replace(' ', '-');
        Function<String, String> pipeline = trim.andThen(lower).andThen(dashes);
        return pipeline.apply(text);
    }
}
